        return ADCS_E_RANGE;
    if (adcs_vec3_normalize(ref_a, ADCS_EPS_NORM, &na) != ADCS_OK)
        return ADCS_E_RANGE;
    if (adcs_vec3_normalize(ref_b, ADCS_EPS_NORM, &nb) != ADCS_OK)
        return ADCS_E_RANGE;
    cross = adcs_vec3_cross(&na, &nb);
    sep = adcs_vec3_norm(&cross);
    if (sep <= ADCS_EPS_COLLINEAR)
        return ADCS_E_DEGENERATE;
    if (variance_a <= variance_b) {
        idx = 0;
        sel_var = variance_a;
        st = adcs_triad(body_a, body_b, &na, &nb, c_bi);
    } else {
        idx = 1;
        sel_var = variance_b;
        st = adcs_triad(body_b, body_a, &nb, &na, c_bi);
